C++ snippet (from a representative example referenced on the Quicksort page context):

#include <bits/stdc++.h>
using namespace std;
int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    vector<int> a; int x;
    // read until EOF
    while (cin >> x) a.push_back(x);
    sort(a.begin(), a.end());
    // Note: indices printed are 0-based in demonstrations
    for (size_t i = 0; i < a.size(); ++i) {
        cout << a[i] << (i+1==a.size()?'\n':' ');
    }
    return 0;
}

Comment notes in context: 'indices are 0-based' in example outputs showing index labels when printed.
